**static_noise.gdshader** (for RadioScope):
```glsl
shader_type canvas_item;

uniform float time_offset = 0.0;
uniform float noise_strength : hint_range(0.0, 2.0) = 1.0;
uniform float signal_strength : hint_range(0.0, 1.0) = 0.0;
uniform float scanline_speed = 40.0;
uniform vec4 tint : source_color = vec4(0.55, 0.85, 0.65, 1.0);
uniform vec4 noise_color : source_color = vec4(0.8, 0.85, 0.9, 1.0);

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void fragment() {
    vec2 uv = UV;
    float t = TIME + time_offset;
    float n = hash(floor(uv * vec2(180.0, 110.0)) + vec2(floor(t * 24.0), floor(t * 17.0)));
    // horizontal tear
    float tear = step(0.985, hash(vec2(floor(uv.y * 60.0), floor(t * 9.0))));
    n = mix(n, hash(floor(uv * vec2(90.0,60.0)) + t*3.0), tear * 0.8);
    // signal waveform
    float wave = 0.0;
    if (signal_strength > 0.001) {
        float w = sin((uv.x * 28.0) + t * 6.0) * 0.5 + 0.5;
        float d = abs(uv.y - (0.5 + (w - 0.5) * 0.55 * signal_strength));
        wave = smoothstep(0.05, 0.0, d) * signal_strength;
    }
    float g = n * noise_strength * (1.0 - signal_strength * 0.75);
    vec3 col = mix(vec3(0.02,0.03,0.04), noise_color.rgb * tint.rgb, clamp(g, 0.0, 1.0));
    col += vec3(0.25, 1.0, 0.45) * wave;
    // rolling scanline
    float sl = 0.5 + 0.5 * sin((uv.y * 3.0 - t * 1.5) * 6.28318);
    col *= 0.85 + 0.15 * sl;
    // dark grid
    float grid = max(step(0.97, fract(uv.x*24.0)), step(0.97, fract(uv.y*14.0)));
    col *= 1.0 - grid*0.25;
    COLOR = vec4(col, 1.0);
}
```

**post_glitch.gdshader** (fullscreen):
```glsl
shader_type canvas_item;

uniform sampler2D screen_tex : hint_screen_texture, filter_linear_mipmap;
uniform float glitch : hint_range(0.0, 1.0) = 0.0;
uniform float time_scale = 1.0;
uniform float vignette : hint_range(0.0, 2.0) = 1.0;
uniform float brightness : hint_range(0.0, 2.0) = 1.0;
uniform vec4 tint : source_color = vec4(1.0);
uniform float desat : hint_range(0.0,1.0) = 0.0;

float hash(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453); }

void fragment(){
    vec2 uv = SCREEN_UV;
    float t = TIME * time_scale;
    float g = glitch;
    // horizontal displacement bands
    float band = floor(uv.y * 40.0);
    float shake = hash(vec2(band, floor(t * 12.0)));
    float disp = (shake - 0.5) * 0.03 * g * step(0.6, hash(vec2(band, floor(t*7.0))));
    uv.x += disp;
    // global jitter
    uv += vec2((hash(vec2(floor(t*30.0), 1.0))-0.5)*0.006*g, (hash(vec2(floor(t*30.0), 2.0))-0.5)*0.004*g);
    // chromatic aberration
    float ca = (0.0015 + 0.012*g);
    vec4 c;
    c.r = texture(screen_tex, uv + vec2(ca, 0.0)).r;
    c.g = texture(screen_tex, uv).g;
    c.b = texture(screen_tex, uv - vec2(ca, 0.0)).b;
    c.a = texture(screen_tex, uv).a;
    // scanlines
    float sl = 0.94 + 0.06*sin(uv.y * 900.0);
    c.rgb *= sl;
    // rolling bright bar
    float rb = smoothstep(0.0, 0.06, abs(fract(uv.y*0.5 - t*0.06) - 0.5));
    c.rgb += (1.0-rb) * 0.06 * (0.3 + g);
    // noise
    float n = hash(floor(uv*vec2(640.0,360.0)) + floor(t*40.0));
    c.rgb += (n - 0.5) * 0.10 * (0.12 + g * 1.3);
    // desaturate
    float lum = dot(c.rgb, vec3(0.299,0.587,0.114));
    c.rgb = mix(c.rgb, vec3(lum), desat);
    c.rgb *= tint.rgb;
    c.rgb *= brightness;
    // vignette
    vec2 v = uv - 0.5;
    float vig = pow(clamp(1.0 - dot(v,v) * 1.9 * vignette, 0.0, 1.0), 1.4);
    c.rgb *= mix(0.25, 1.0, vig);
    COLOR = c;
}
```

