**window_night.gdshader**: draws dark night sky outside with a horizon, distant sea, stars, and shadow shapes.
```glsl
shader_type canvas_item;
uniform float darkness = 1.0;
uniform float shape_presence = 0.0; // 0..1
uniform float time_seed = 0.0;
uniform vec4 sky_color : source_color = vec4(0.02,0.04,0.07,1.0);
uniform vec4 sea_color : source_color = vec4(0.01,0.02,0.03,1.0);

float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453); }
float noise2(vec2 p){
    vec2 i = floor(p); vec2 f = fract(p);
    f = f*f*(3.0-2.0*f);
    return mix(mix(hash(i), hash(i+vec2(1,0)), f.x), mix(hash(i+vec2(0,1)), hash(i+vec2(1,1)), f.x), f.y);
}

void fragment(){
    vec2 uv = UV;
    float horizon = 0.62;
    vec3 col;
    if (uv.y < horizon) {
        // sky gradient
        col = mix(sky_color.rgb, vec3(0.06, 0.07, 0.10), uv.y / horizon);
        // stars
        float s = hash(floor(uv*vec2(90.0,50.0)));
        float tw = 0.5 + 0.5*sin(TIME*2.0 + s*30.0);
        col += vec3(0.5,0.6,0.75) * step(0.985, s) * tw * 0.7;
    } else {
        float depth = (uv.y - horizon) / (1.0 - horizon);
        col = mix(vec3(0.03,0.05,0.07), sea_color.rgb, depth);
        // waves
        float w = noise2(vec2(uv.x*22.0, uv.y*40.0 - TIME*0.35));
        col += vec3(0.06,0.09,0.11) * smoothstep(0.55,1.0,w) * (0.4 + darkness*0.3);
        // faint signal glint
    }
    // the shape outside
    float t = TIME*0.25 + time_seed;
    float sx = 0.5 + sin(t*0.7)*0.35;
    float sh = sin(t*1.7)*0.06;
    vec2 c = vec2(sx, horizon - 0.22 + sh);
    float d = length((uv - c) * vec2(1.0, 1.25));
    float body = smoothstep(0.30, 0.10, d);
    col = mix(col, vec3(0.0), body * shape_presence * 0.95);
    // tendrils
    ...
    col *= darkness;
    COLOR = vec4(col, 1.0);
}
```
