arguments.content:
shader_type canvas_item;

// CRT / interference post process used on the whole viewport.

uniform sampler2D screen_tex : hint_screen_texture, filter_linear_mipmap;
uniform float glitch : hint_range(0.0, 1.0) = 0.0;
uniform float time_scale = 1.0;
uniform float vignette_strength : hint_range(0.0, 2.0) = 1.0;
uniform float brightness : hint_range(0.0, 2.0) = 1.0;
uniform float desat : hint_range(0.0, 1.0) = 0.2;
uniform float corruption : hint_range(0.0, 1.0) = 0.0;
uniform vec4 tint : source_color = vec4(1.0, 1.0, 1.0, 1.0);

float hsh(vec2 p) {
	return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5453);
}

void fragment() {
	vec2 uv = SCREEN_UV;
	float t = TIME * time_scale;
	float g = clamp(glitch, 0.0, 1.0);

	// horizontal displacement bands
	float band = floor(uv.y * 46.0);
	float pick = hsh(vec2(band, floor(t * 11.0)));
	float disp = (hsh(vec2(band, floor(t * 7.0))) - 0.5) * 0.05 * g * step(0.62, pick);
	uv.x += disp;

	// global micro jitter
	uv.x += (hsh(vec2(floor(t * 27.0), 1.0)) - 0.5) * 0.008 * g;
	uv.y += (hsh(vec2(floor(t * 27.0), 2.0)) - 0.5) * 0.006 * g;

	// chromatic aberration
	float ca = 0.0012 + 0.014 * g;
	vec4 c;
	c.r = texture(screen_tex, uv + vec2(ca, 0.0)).r;
	c.g = texture(screen_tex, uv).g;
	c.b = texture(screen_tex, uv - vec2(ca, 0.0)).b;
	c.a = texture(screen_tex, uv).a;

	// scanlines
	c.rgb *= 0.93 + 0.07 * sin(uv.y * 820.0);

	// rolling bright bar
	float roll = abs(fract(uv.y * 0.5 - t * 0.05) - 0.5);
	c.rgb += smoothstep(0.09, 0.0, roll) * 0.05 * (0.35 + g);

	// film grain
	float n = hsh(floor(uv * vec2(620.0, 340.0)) + floor(t * 38.0));
	c.rgb += (n - 0.5) * (0.045 + g * 0.16 + corruption * 0.10);

	// dead pixels / data blocks
	float blk = step(0.9975, hsh(floor(uv * vec2(58.0, 32.0)) + floor(t * 5.0)));
	c.rgb = mix(c.rgb, vec3(0.35, 0.95, 0.65) * hsh(vec2(t, uv.x)), blk * (0.15 + corruption * 0.6));

	// saturation
	float lum = dot(c.rgb, vec3(0.299, 0.587, 0.114));
	c.rgb = mix(c.rgb, vec3(lum), clamp(desat, 0.0, 1.0));

	c.rgb *= tint.rgb;
	c.rgb *= brightness;

	// vignette
	vec2 v = uv - vec2(0.5);
	float vig = pow(clamp(1.0 - dot(v, v) * 1.85 * vignette_strength, 0.0, 1.0), 1.35);
	c.rgb *= mix(0.18, 1.0, vig);

	COLOR = vec4(c.rgb, 1.0);
}

shader_type canvas_item;

// Static / carrier scope displayed on the radio faceplate.

uniform float noise_strength : hint_range(0.0, 2.0) = 1.0;
uniform float signal_strength : hint_range(0.0, 1.0) = 0.0;
uniform float jam_level : hint_range(0.0, 1.0) = 0.0;
uniform float seed = 0.0;
uniform vec4 glow : source_color = vec4(0.42, 0.98, 0.62, 1.0);
uniform vec4 base_color : source_color = vec4(0.015, 0.03, 0.035, 1.0);

float hsh(vec2 p) {
	return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void fragment() {
	vec2 uv = UV;
	float t = TIME + seed;

	float grains = hsh(floor(uv * vec2(200.0, 120.0)) + vec2(floor(t * 26.0), floor(t * 19.0)));
	float fine = hsh(floor(uv * vec2(90.0, 54.0)) + vec2(floor(t * 14.0), floor(t * 11.0)));
	float n = mix(grains, fine, 0.45);

	// horizontal tearing during jamming
	float tear_row = step(0.90, hsh(vec2(floor(uv.y * 40.0), floor(t * 9.0))));
	n = mix(n, hsh(vec2(floor(uv.y * 12.0), floor(t * 30.0))), tear_row * (0.25 + jam_level * 0.7));

	// carrier waveform
	float wave = 0.0;
	if (signal_strength > 0.001) {
		float w = sin(uv.x * 30.0 + t * 5.0) * 0.5 + 0.5;
		float w2 = sin(uv.x * 61.0 - t * 9.0) * 0.5 + 0.5;
		float shape = mix(w, w2, 0.35) * 0.62 + 0.19;
		float d = abs(uv.y - shape);
		wave = smoothstep(0.016, 0.0, d) * signal_strength;
	}

	vec3 col = base_color.rgb;
	col += glow.rgb * n * noise_strength * (1.0 - signal_strength * 0.72);
	col += glow.rgb * wave * 1.15;
	col += vec3(1.0, 0.35, 0.28) * jam_level * n * 0.55;

	// rolling scanline
	col *= 0.82 + 0.18 * (0.5 + 0.5 * sin(uv.y * 6.28318 * 3.0 - t * 1.6));

	// graticule
	float grid = max(step(0.972, fract(uv.x * 18.0)), step(0.955, fract(uv.y * 10.0)));
	col *= 1.0 - grid * 0.35;

	// edge falloff
	vec2 e = min(uv, 1.0 - uv);
	col *= smoothstep(0.0, 0.035, min(e.x, e.y));

	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;

// Night view through the station window. Something moves out there.

uniform float darkness : hint_range(0.0, 1.0) = 1.0;
uniform float shape_presence : hint_range(0.0, 1.0) = 0.0;
uniform float shape_seed = 0.0;
uniform float light_bleed : hint_range(0.0, 1.0) = 0.5;
uniform vec4 sky_top : source_color = vec4(0.020, 0.035, 0.062, 1.0);
uniform vec4 sky_bottom : source_color = vec4(0.055, 0.075, 0.105, 1.0);
uniform vec4 sea_color : source_color = vec4(0.010, 0.020, 0.030, 1.0);

float hsh(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

float vnoise(vec2 p) {
	vec2 i = floor(p);
	vec2 f = fract(p);
	f = f * f * (3.0 - 2.0 * f);
	float a = hsh(i);
	float b = hsh(i + vec2(1.0, 0.0));
	float c = hsh(i + vec2(0.0, 1.0));
	float d = hsh(i + vec2(1.0, 1.0));
	return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

void fragment() {
	vec2 uv = UV;
	float horizon = 0.63;
	vec3 col;

	if (uv.y < horizon) {
		float k = uv.y / horizon;
		col = mix(sky_top.rgb, sky_bottom.rgb, k);
		float s = hsh(floor(uv * vec2(110.0, 60.0)));
		float tw = 0.45 + 0.55 * sin(TIME * 1.7 + s * 41.0);
		col += vec3(0.55, 0.66, 0.80) * step(0.977, s) * tw * 0.75;
		// slow cloud band
		float cl = vnoise(vec2(uv.x * 4.0 + TIME * 0.02, uv.y * 7.0));
		col += vec3(0.02, 0.028, 0.038) * smoothstep(0.5, 0.95, cl);
	} else {
		float depth = (uv.y - horizon) / (1.0 - horizon);
		col = mix(vec3(0.030, 0.048, 0.062), sea_color.rgb, depth);
		float w = vnoise(vec2(uv.x * 26.0, uv.y * 46.0 - TIME * 0.22));
		float w2 = vnoise(vec2(uv.x * 60.0 - 3.0, uv.y * 90.0 - TIME * 0.4));
		col += vec3(0.05, 0.075, 0.09) * smoothstep(0.52, 1.0, w) * (0.55 + darkness * 0.35);
		col += vec3(0.07, 0.10, 0.11) * smoothstep(0.86, 1.0, w2) * 0.5;
	}

	// the shape beyond the glass
	float t = TIME * 0.22 + shape_seed;
	float drift = sin(t * 0.61) * 0.33;
	vec2 c = vec2(0.5 + drift, horizon - 0.16 + sin(t * 1.31) * 0.05);
	vec2 rel = (uv - c) * vec2(1.0, 1.35);
	float body = smoothstep(0.26, 0.07, length(rel));
	float pillar = smoothstep(0.55, 0.05, abs(rel.x) * 14.0) * smoothstep(0.62, 0.05, rel.y + 0.18);
	float tendril = 0.0;
	for (int i = 0; i < 3; i++) {
		float fi = float(i);
		float off = sin(t * (1.1 + fi * 0.4) + fi * 2.1) * 0.16;
		float d = length((uv - vec2(c.x + off, horizon - 0.02 - fi * 0.03)) * vec2(1.0, 0.9));
		tendril = max(tendril, smoothstep(0.10 - fi * 0.02, 0.0, d));
	}
	float shape = clamp(max(body, max(pillar * 0.9, tendril)) * shape_presence, 0.0, 1.0);
	col = mix(col, vec3(0.0, 0.0, 0.0), shape * 0.96);

	// two dim lights far out on the water when the shape is near
	if (shape_presence > 0.2) {
		vec2 eye = vec2(c.x + 0.055, c.y + 0.015);
		float e = smoothstep(0.012, 0.0, length((uv - eye) * vec2(1.0, 1.0)));
		col = mix(col, vec3(0.9, 0.18, 0.12), e * shape_presence);
	}

	// faint reflection of the console light on the glass
	float sq = smoothstep(0.75, 0.1, abs(uv.x - 0.30) + abs(uv.y - 0.95) * 2.2);
	col += vec3(0.10, 0.14, 0.09) * sq * light_bleed;

	// glass streaks
	float streak = vnoise(vec2(uv.x * 3.0, uv.y * 22.0 + TIME * 0.05));
	col += vec3(0.012) * smoothstep(0.72, 1.0, streak);

	col *= mix(0.55, 1.0, darkness);

	// window frame vignette
	vec2 e2 = min(uv, 1.0 - uv);
	col *= smoothstep(0.0, 0.02, min(e2.x, e2.y));

	COLOR = vec4(col, 1.0);
}

shader_type canvas_item;
render_mode blend_add;

// Additive radial glow used for the radio lamp and console bounce light.

uniform vec2 uv_center = vec2(0.5, 0.5);
uniform vec2 uv_scale = vec2(1.0, 1.0);
uniform float radius : hint_range(0.01, 2.0) = 0.4;
uniform vec4 glow_color : source_color = vec4(1.0, 0.62, 0.28, 1.0);
uniform float strength : hint_range(0.0, 3.0) = 1.0;
uniform float falloff : hint_range(0.5, 6.0) = 2.4;

void fragment() {
	vec2 p = (UV - uv_center) * uv_scale;
	float d = length(p) / max(radius, 0.0001);
	float f = pow(clamp(1.0 - d, 0.0, 1.0), falloff);
	COLOR = vec4(glow_color.rgb * f * strength, f * glow_color.a * clamp(strength, 0.0, 1.0));
}

extends Control
# The chart table. Draws the sector chart, grid, placed pins and the
# triangulation geometry. Emits the estimated position when clicked.

signal pin_requested(lat: float, lon: float)

const LAT_MIN := 40.0
const LAT_MAX := 56.0
const LON_MIN := 8.0
const LON_MAX := 24.0
const STATION_LAT := 52.0
const STATION_LON := 18.0

var pins: Array = []
var pending: Dictionary = {}
var show_source := false
var source_geo := Vector2(53.0, 17.5)
var source_lock := 0.0
var corruption := 0.0
var light := 1.0
var sweep := 0.0
var flash := 0.0
var flash_pos := Vector2.ZERO
var alarm := 0.0
var cursor_enabled := true

var _hover := Vector2(-9999.0, -9999.0)
var _t := 0.0
var _font: Font


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	clip_contents = true
	_font = load("res://assets/fonts/KenneyFutureNarrow.ttf")
	set_process(true)


func geo_to_local(lat: float, lon: float) -> Vector2:
	var x := (LON_MAX - lon) / (LON_MAX - LON_MIN) * size.x
	var y := (LAT_MAX - lat) / (LAT_MAX - LAT_MIN) * size.y
	return Vector2(x, y)


func local_to_geo(p: Vector2) -> Vector2:
	var lon := LON_MAX - clampf(p.x / maxf(size.x, 1.0), 0.0, 1.0) * (LON_MAX - LON_MIN)
	var lat := LAT_MAX - clampf(p.y / maxf(size.y, 1.0), 0.0, 1.0) * (LAT_MAX - LAT_MIN)
	return Vector2(lat, lon)


func add_pin(id: int, lat: float, lon: float, cache: bool) -> void:
	pins.append({"id": id, "lat": lat, "lon": lon, "cache": cache, "t": 0.0})


func _process(delta: float) -> void:
	_t += delta
	sweep = fmod(sweep + delta * 0.9, TAU)
	flash = maxf(0.0, flash - delta * 2.2)
	alarm = maxf(0.0, alarm - delta * 1.5)
	if pending.is_empty() and not show_source:
		source_lock = 0.0
	else:
		source_lock = clampf(source_lock + delta * 0.6, 0.0, 1.0)
	for p in pins:
		p["t"] = minf(1.0, float(p["t"]) + delta * 3.0)
	queue_redraw()


func _gui_input(event: InputEvent) -> void:
	if event is InputEventMouseMotion:
		_hover = (event as InputEventMouseMotion).position
	elif event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		if mb.button_index == MOUSE_BUTTON_LEFT and mb.pressed:
			var g := local_to_geo(mb.position)
			pin_requested.emit(g.x, g.y)
			accept_event()


func _notification(what: int) -> void:
	if what == NOTIFICATION_MOUSE_EXIT:
		_hover = Vector2(-9999.0, -9999.0)


func _draw() -> void:
	var s := size
	var dim := lerpf(0.55, 1.0, light)

	# chart paper
	draw_rect(Rect2(Vector2.ZERO, s), Color(0.052, 0.075, 0.086) * dim)
	# sea hatching
	var sea := Color(0.075, 0.115, 0.135) * dim
	var y := 0.0
	while y < s.y:
		draw_line(Vector2(0, y), Vector2(s.x, y + 3.0), Color(sea.r, sea.g, sea.b, 0.35), 1.0)
		y += 9.0

	# land masses
	var land := Color(0.115, 0.128, 0.118) * dim
	var land_hi := Color(0.155, 0.168, 0.150) * dim
	var coast: Array = [
		[Vector2(0.60, 0.0), Vector2(1.0, 0.0), Vector2(1.0, 0.30), Vector2(0.88, 0.27), Vector2(0.79, 0.21), Vector2(0.72, 0.10), Vector2(0.60, 0.0)],
		[Vector2(0.15, 0.74), Vector2(0.27, 0.69), Vector2(0.32, 0.79), Vector2(0.25, 0.88), Vector2(0.13, 0.83)],
		[Vector2(0.42, 0.50), Vector2(0.51, 0.46), Vector2(0.55, 0.55), Vector2(0.47, 0.61), Vector2(0.40, 0.56)],
		[Vector2(0.84, 0.60), Vector2(0.94, 0.56), Vector2(0.99, 0.68), Vector2(0.90, 0.77), Vector2(0.81, 0.70)]
	]
	for poly in coast:
		var pts := PackedVector2Array()
		for p in poly:
			pts.append(Vector2(p.x * s.x, p.y * s.y))
		draw_colored_polygon(pts, land)
		var outline := pts.duplicate()
		outline.append(pts[0])
		draw_polyline(outline, land_hi, 1.5)
	# skerries
	draw_circle(Vector2(0.34 * s.x, 0.30 * s.y), 3.5, land)
	draw_circle(Vector2(0.63 * s.x, 0.72 * s.y), 2.5, land)
	draw_circle(Vector2(0.72 * s.x, 0.42 * s.y), 2.0, land)

	# latitude / longitude grid
	var grid_col := Color(0.16, 0.30, 0.30, 0.55) * dim
	var lon := LON_MIN
	while lon <= LON_MAX + 0.01:
		var x := geo_to_local(0.0, lon).x
		draw_line(Vector2(x, 0), Vector2(x, s.y), grid_col, 1.0)
		lon += 2.0
	var lat := LAT_MIN
	while lat <= LAT_MAX + 0.01:
		var yy := geo_to_local(lat, 0.0).y
		draw_line(Vector2(0, yy), Vector2(s.x, yy), grid_col, 1.0)
		lat += 2.0
	# heavier equator-ish meridian
	var cx := geo_to_local(0.0, 18.0).x
	draw_line(Vector2(cx, 0), Vector2(cx, s.y), Color(0.24, 0.44, 0.42, 0.5) * dim, 1.0)

	# graticule labels
	if _font != null:
		var lc := Color(0.34, 0.55, 0.52) * dim
		lon = LON_MIN
		while lon <= LON_MAX + 0.01:
			var x2 := geo_to_local(0.0, lon).x
			var txt := "%dW" % int(lon)
			draw_string(_font, Vector2(x2 + 3.0, 11.0), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 10, lc)
			lon += 4.0
		lat = LAT_MIN
		while lat <= LAT_MAX + 0.01:
			var y2 := geo_to_local(lat, 0.0).y
			draw_string(_font, Vector2(3.0, y2 - 3.0), "%dN" % int(lat), HORIZONTAL_ALIGNMENT_LEFT, -1, 10, lc)
			lat += 4.0

	# radar sweep from the station
	var st := geo_to_local(STATION_LAT, STATION_LON)
	var sweep_len := s.length() * 0.85
	var dir := Vector2(cos(sweep), sin(sweep))
	var steps := 26
	for i in range(steps):
		var a := float(i) / float(steps)
		var p1 := st + dir * sweep_len * a
		if not Rect2(Vector2.ZERO, s).has_point(p1):
			continue
		draw_line(st, p1, Color(0.25, 0.95, 0.60, 0.30 * (1.0 - a)), 1.0)

	# range rings around home
	for i in range(1, 4):
		var r := float(i) * s.x * 0.16
		draw_arc(st, r, 0.0, TAU, 64, Color(0.22, 0.50, 0.42, 0.28 * dim), 1.0)

	# triangulation geometry
	if pins.size() >= 3:
		var pts := PackedVector2Array()
		for p in pins:
			pts.append(geo_to_local(float(p["lat"]), float(p["lon"])))
		for i in range(pts.size()):
			var a2: Vector2 = pts[i]
			var b2: Vector2 = pts[(i + 1) % pts.size()]
			_dashed_line(a2, b2, Color(0.95, 0.72, 0.30, 0.55), 1.0)
		var centroid := Vector2.ZERO
		for p in pts:
			centroid += p
		centroid /= float(pts.size())
		draw_circle(centroid, 5.0, Color(0.95, 0.35, 0.28, 0.85))
		draw_arc(centroid, 14.0 + sin(_t * 3.0) * 3.0, 0.0, TAU, 32, Color(0.95, 0.35, 0.28, 0.5), 1.5)

	# resolved source marker
	if show_source:
		var sp := geo_to_local(source_geo.x, source_geo.y)
		var pulse := 0.5 + 0.5 * sin(_t * 4.0)
		draw_arc(sp, 10.0 + pulse * 12.0, 0.0, TAU, 40, Color(1.0, 0.20, 0.16, (0.9 - pulse * 0.5) * source_lock), 2.0)
		draw_arc(sp, 22.0 + pulse * 14.0, 0.0, TAU, 40, Color(1.0, 0.20, 0.16, (0.5 - pulse * 0.3) * source_lock), 1.0)
		draw_line(sp - Vector2(16, 0), sp + Vector2(16, 0), Color(1.0, 0.35, 0.3, source_lock), 1.0)
		draw_line(sp - Vector2(0, 16), sp + Vector2(0, 16), Color(1.0, 0.35, 0.3, source_lock), 1.0)

	# placed pins
	for p in pins:
		var lp := geo_to_local(float(p["lat"]), float(p["lon"]))
		var t := float(p["t"])
		var col := Color(0.98, 0.30, 0.24) if not bool(p["cache"]) else Color(0.40, 0.95, 0.55)
		draw_line(lp, lp - Vector2(0, 14.0 * t), col, 1.5)
		draw_circle(lp - Vector2(0, 14.0 * t), 4.5 * t, col)
		draw_arc(lp, 7.0 * t, 0.0, TAU, 20, Color(col.r, col.g, col.b, 0.6), 1.0)
		if _font != null:
			draw_string(_font, lp + Vector2(7, 4), str(int(p["id"]) + 1), HORIZONTAL_ALIGNMENT_LEFT, -1, 11, Color(0.92, 0.94, 0.9, 0.85))

	# home station marker
	draw_circle(st, 5.0, Color(0.45, 0.95, 0.90))
	draw_arc(st, 9.0, 0.0, TAU, 24, Color(0.45, 0.95, 0.90, 0.7), 1.0)
	if _font != null:
		draw_string(_font, st + Vector2(11, -6), "KESTREL-9", HORIZONTAL_ALIGNMENT_LEFT, -1, 11, Color(0.55, 0.95, 0.92, 0.9))

	# pending target box (a bracket at the estimated spot is NOT drawn; the
	# operator must read the coordinates themselves)

	# hover crosshair
	if cursor_enabled and is_visible_in_tree() and _hover.x > -9000.0:
		var hc := Color(0.55, 0.95, 0.85, 0.55)
		draw_line(Vector2(_hover.x, 0), Vector2(_hover.x, s.y), Color(hc.r, hc.g, hc.b, 0.25), 1.0)
		draw_line(Vector2(0, _hover.y), Vector2(s.x, _hover.y), Color(hc.r, hc.g, hc.b, 0.25), 1.0)
		var box := Rect2(_hover - Vector2(9, 9), Vector2(18, 18))
		draw_rect(box, hc, false, 1.0)

	# flash feedback
	if flash > 0.0:
		draw_rect(Rect2(Vector2.ZERO, s), Color(0.95, 0.30, 0.25, flash * 0.35))
		draw_arc(flash_pos, 18.0 + (1.0 - flash) * 30.0, 0.0, TAU, 32, Color(0.95, 0.4, 0.3, flash), 2.0)

	# frame
	draw_rect(Rect2(Vector2.ZERO, s), Color(0.30, 0.42, 0.40, 0.85), false, 2.0)
	var corner := Color(0.55, 0.95, 0.80, 0.9)
	var c := 16.0
	draw_line(Vector2(0, 0), Vector2(c, 0), corner, 2.0)
	draw_line(Vector2(0, 0), Vector2(0, c), corner, 2.0)
	draw_line(Vector2(s.x, 0), Vector2(s.x - c, 0), corner, 2.0)
	draw_line(Vector2(s.x, 0), Vector2(s.x, c), corner, 2.0)
	draw_line(Vector2(0, s.y), Vector2(c, s.y), corner, 2.0)
	draw_line(Vector2(0, s.y), Vector2(0, s.y - c), corner, 2.0)
	draw_line(Vector2(s.x, s.y), Vector2(s.x - c, s.y), corner, 2.0)
	draw_line(Vector2(s.x, s.y), Vector2(s.x, s.y - c), corner, 2.0)

	# corruption static
	if corruption > 0.02:
		var n := int(corruption * 34.0)
		for i in range(n):
			var rx := fmod(sin(float(i) * 12.9898 + _t * 3.1) * 43758.5453, 1.0)
			var ry := fmod(sin(float(i) * 78.233 + _t * 2.3) * 12543.113, 1.0)
			rx = absf(rx)
			ry = absf(ry)
			var p := Vector2(rx * s.x, ry * s.y)
			draw_rect(Rect2(p, Vector2(randf_range(6, 40), 1.0)), Color(0.4, 0.95, 0.7, corruption * 0.25))


func _dashed_line(a: Vector2, b: Vector2, col: Color, width: float) -> void:
	var total := a.distance_to(b)
	if total < 1.0:
		return
	var dash := 7.0
	var gap := 5.0
	var dir := (b - a) / total
	var d := 0.0
	while d < total:
		var e := minf(d + dash, total)
		draw_line(a + dir * d, a + dir * e, col, width)
		d = e + gap

extends Control
# Horizontal tuning dial. Mouse drag, wheel or arrow keys move the carrier.

signal tuned(value: float)
signal drag_started
signal drag_ended

const FREQ_MIN := 87.0
const FREQ_MAX := 108.0

var value := 87.0
var locked_freqs: Array = []
var jam_band := Vector2.ZERO
var jam_active := false
var enabled := true
var noise := 0.0

var _dragging := false
var _font: Font
var _hover := false


func _ready() -> void:
	mouse_filter = Control.MOUSE_FILTER_STOP
	focus_mode = Control.FOCUS_ALL
	_font = load("res://assets/fonts/KenneyFutureNarrow.ttf")


func set_value(v: float, emit_signal_too: bool = false) -> void:
	var nv := clampf(v, FREQ_MIN, FREQ_MAX)
	if absf(nv - value) < 0.0005:
		return
	value = nv
	queue_redraw()
	if emit_signal_too:
		tuned.emit(value)


func _pad() -> float:
	return 20.0


func _x_for(f: float) -> float:
	return _pad() + (clampf(f, FREQ_MIN, FREQ_MAX) - FREQ_MIN) / (FREQ_MAX - FREQ_MIN) * (size.x - _pad() * 2.0)


func _f_for(x: float) -> float:
	var t := clampf((x - _pad()) / maxf(size.x - _pad() * 2.0, 1.0), 0.0, 1.0)
	return FREQ_MIN + t * (FREQ_MAX - FREQ_MIN)


func _gui_input(event: InputEvent) -> void:
	if not enabled:
		return
	if event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		if mb.button_index == MOUSE_BUTTON_LEFT:
			if mb.pressed:
				_dragging = true
				focus_mode = Control.FOCUS_ALL
				grab_focus()
				drag_started.emit()
				set_value(_f_for(mb.position.x), true)
			else:
				if _dragging:
					_dragging = false
					drag_ended.emit()
			accept_event()
		elif mb.pressed and mb.button_index == MOUSE_BUTTON_WHEEL_UP:
			set_value(value + 0.05, true)
			accept_event()
		elif mb.pressed and mb.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			set_value(value - 0.05, true)
			accept_event()
	elif event is InputEventMouseMotion:
		var mm := event as InputEventMouseMotion
		if _dragging:
			set_value(_f_for(mm.position.x), true)
			accept_event()
	else:
		_hover = true


func _notification(what: int) -> void:
	if what == NOTIFICATION_MOUSE_ENTER:
		_hover = true
		queue_redraw()
	elif what == NOTIFICATION_MOUSE_EXIT:
		_hover = false
		queue_redraw()


func _process(delta: float) -> void:
	if not enabled:
		return
	var step := 0.0
	if Input.is_key_pressed(KEY_LEFT) or Input.is_key_pressed(KEY_A):
		step = -1.0
	elif Input.is_key_pressed(KEY_RIGHT) or Input.is_key_pressed(KEY_D):
		step = 1.0
	if step != 0.0:
		var fine := 0.02 if (Input.is_key_pressed(KEY_SHIFT)) else 0.14
		set_value(value + step * fine * delta * 22.0, true)


func _draw() -> void:
	var cy := size.y * 0.62
	var x0 := _pad()
	var x1 := size.x - _pad()
	var track_h := 12.0

	# faceplate
	draw_rect(Rect2(Vector2(0, 0), size), Color(0.045, 0.052, 0.058))
	draw_rect(Rect2(Vector2(0, 0), size), Color(0.22, 0.30, 0.30, 0.8), false, 1.0)

	# band scale background
	var band_rect := Rect2(Vector2(x0, cy - track_h * 0.5), Vector2(x1 - x0, track_h))
	draw_rect(band_rect, Color(0.075, 0.10, 0.10))
	draw_rect(band_rect, Color(0.20, 0.40, 0.36, 0.7), false, 1.0)

	# jam band
	if jam_active:
		var jx0 := _x_for(jam_band.x)
		var jx1 := _x_for(jam_band.y)
		var jr := Rect2(Vector2(jx0, cy - track_h * 0.5 - 6.0), Vector2(maxf(jx1 - jx0, 2.0), track_h + 12.0))
		draw_rect(jr, Color(0.85, 0.16, 0.12, 0.30 + 0.12 * sin(noise * 9.0)))
		var hx := jr.position.x
		while hx < jr.end.x:
			draw_line(Vector2(hx, jr.end.y), Vector2(minf(hx + 7.0, jr.end.x), jr.position.y), Color(0.95, 0.3, 0.22, 0.55), 1.0)
			hx += 9.0
		draw_rect(jr, Color(0.95, 0.32, 0.22, 0.8), false, 1.0)

	# ticks
	var f := FREQ_MIN
	while f <= FREQ_MAX + 0.001:
		var x := _x_for(f)
		var local := fmod(f, 3.0)
		var is_lab := absf(local) < 0.01 or absf(local - 3.0) < 0.01
		var big := absf(fmod(f, 1.0)) < 0.001
		var h := 12.0 if is_lab else (8.0 if big else 5.0)
		var col := Color(0.35, 0.62, 0.55, 0.95) if is_lab else Color(0.28, 0.48, 0.44, 0.7)
		draw_line(Vector2(x, cy - track_h * 0.5 - 2.0), Vector2(x, cy - track_h * 0.5 - 2.0 - h), col, 1.0)
		if is_lab and _font != null:
			draw_string(_font, Vector2(x - 10.0, cy - track_h * 0.5 - 18.0), "%d" % int(f), HORIZONTAL_ALIGNMENT_CENTER, 20.0, 11, Color(0.42, 0.72, 0.64, 0.9))
		f += 0.5

	# locked markers
	for lf in locked_freqs:
		var lx := _x_for(float(lf))
		draw_line(Vector2(lx, cy + track_h * 0.5 + 3.0), Vector2(lx, cy + track_h * 0.5 + 13.0), Color(0.35, 0.98, 0.55, 0.95), 2.0)
